import test from 'node:test';import assert from 'node:assert/strict';import {readFileSync} from 'node:fs';
import {hashBytes,importPackage} from '../src/package';import {ensurePianoReady} from '../src/piano-readiness';
// Generated by exact accepted Viewer 94ef94b + retained ISO da93cf9, not by
// the identity implementation under test. Musical data is newly authored.
const bytes=new Uint8Array(readFileSync(new URL('../fixtures/authored-preparation-v1.tuna',import.meta.url)));
test('an independently frozen v1 edition cold-reads exact bytes',async()=>{
 assert.equal(await hashBytes(bytes),'5c94ab9d3eb78f2109b04129fc065c220705f611137f3f1a7325dffb1012f52f');
 const p=await importPackage(bytes);assert.equal(p.preparationIdentity!.version,'viewer-piano-preparation-v1');
 assert.equal(p.preparationIdentity!.sha256,'2f4bc1a0f1ecd44ea66ce497434cd3b9f2e9e83fce4e102639f936a9c22cba01');
 const retained=await ensurePianoReady({packageBytes:bytes,layout:'janko-four-row'});
 assert.equal(retained.status,'editable','message' in retained?retained.message:undefined);assert.deepEqual(retained.packageBytes,bytes);
});
